{
  "category_edits": [
    {
      "category": "network_architecture",
      "rationale": "Add a jointly trained residual bottleneck after each GRU output, with width max(8, hidden_units // 4) and a zero-initialized output projection. This initially preserves GRU behavior while allowing nonlinear refinement. Keep embeddings, readout, scoring, loss, optimizer and routing unchanged; persist the bottleneck width for predictor reconstruction.",
      "edits": [
        {
          "find": "                 dropout_rate: float = 0.1):\n        super().__init__()",
          "replace": "                 dropout_rate: float = 0.1, residual_width: int | None = None):\n        super().__init__()"
        },
        {
          "find": "        self.dropout = nn.Dropout(dropout_rate)\n        with torch.no_grad():\n            nn.init.xavier_uniform_(self.item_emb.weight)\n            self.item_emb.weight[0].zero_()",
          "replace": "        self.dropout = nn.Dropout(dropout_rate)\n        with torch.no_grad():\n            nn.init.xavier_uniform_(self.item_emb.weight)\n            self.item_emb.weight[0].zero_()\n        self.residual_width = max(8, hidden_units // 4) if residual_width is None else residual_width\n        self.residual = nn.Sequential(\n            nn.Linear(hidden_units, self.residual_width),\n            nn.GELU(),\n            nn.Linear(self.residual_width, hidden_units),\n        )\n        nn.init.zeros_(self.residual[2].weight)\n        nn.init.zeros_(self.residual[2].bias)"
        },
        {
          "find": "        out, _ = self.gru(emb)\n        # Histories are LEFT padded; count-1 indexes padding on short histories.",
          "replace": "        out, _ = self.gru(emb)\n        out = out + self.residual(out)\n        # Histories are LEFT padded; count-1 indexes padding on short histories."
        },
        {
          "find": "        out, _ = self.gru(emb)\n        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)",
          "replace": "        out, _ = self.gru(emb)\n        out = out + self.residual(out)\n        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)"
        },
        {
          "find": "            \"dropout_rate\": DROPOUT_RATE,\n        }, f)",
          "replace": "            \"dropout_rate\": DROPOUT_RATE,\n            \"residual_width\": model.residual_width,\n        }, f)"
        },
        {
          "find": "            num_layers=meta[\"num_layers\"],\n            dropout_rate=0.0,\n        ).to(_device)",
          "replace": "            num_layers=meta[\"num_layers\"],\n            dropout_rate=0.0,\n            residual_width=meta[\"residual_width\"],\n        ).to(_device)"
        }
      ]
    }
  ],
  "change_summary": "Add a zero-initialized residual GELU bottleneck to GRU outputs in training and inference, with matching checkpoint metadata and predictor construction. Retain one model per category and existing training settings."
}
